"""English report of measured reward-guided search, never estimated timings."""
from collections import defaultdict
import json
import statistics as st

import numpy as np

import settings
from reports import CSS, esc, table, card

ROOT=settings.HERE/'search'


def name(row):
    if row['kind']=='single':return 'Single sample'
    if row['kind']=='best_of_n':return 'Full-utterance Best-of-8'
    return f"{'Winner-of-8' if row['beam_width']==1 else 'Top-2 / budget 8'} · {row['chunk_frames']*80} ms"


def quality_table(rows,emotion):
    grouped=defaultdict(list)
    for row in rows:grouped[name(row)].append(row)
    output=[]
    for label,group in sorted(grouped.items()):
        mean=lambda key:st.mean(x['final'][key] for x in group)
        ranks=[emotion[x['id']]['rank_percentile'] for x in group if x['id'] in emotion]
        output.append([label,str(len(group)),f"{mean('prefix_wer')*100:.2f}",
            f"{mean('clap'):.3f}",f"{mean('genuineness'):.3f}",f"{mean('blend'):.3f}",
            f"{mean('reward'):.3f}",f'{st.mean(ranks):.3f}' if ranks else 'pending'])
    return table(['Method','Takes','Raw WER % ↓','Style CLAP ↑','Genuine /6 ↑','Blend /10 ↑','Selection reward ↑','Held-out EIV rank percentile ↑'],output)


def paired(rows):
    groups=defaultdict(dict)
    for row in rows:groups[name(row)][(row['case'],row['seed'])]=row
    baseline=groups.get('Full-utterance Best-of-8',{})
    output=[]
    rng=np.random.default_rng(1827)
    for method,group in sorted(groups.items()):
        if method=='Full-utterance Best-of-8':continue
        for field in ['prefix_wer','clap','genuineness','reward']:
            blocks=defaultdict(list)
            for key,row in group.items():
                if key in baseline:blocks[key[0]].append(row['final'][field]-baseline[key]['final'][field])
            if not blocks:continue
            values=np.array([st.mean(x) for x in blocks.values()])
            draws=rng.choice(values,size=(5000,len(values)),replace=True).mean(1)
            low,high=np.quantile(draws,[.025,.975])
            output.append([method,field,f'{values.mean():+.4f}',f'[{low:+.4f}, {high:+.4f}]'])
    return table(['Method − Best-of-8','Metric','Mean paired delta','Descriptive 95% text-cluster interval'],output)


def main():
    rows=[]
    for phase in ['smoke','measure','quality','audit']:
        rows.extend(json.loads(p.read_text()) for p in sorted(ROOT.glob(phase+'-*.json')))
    valid=[r for r in rows if not r.get('error')]
    measures=[r for r in valid if r['phase']=='measure']
    quality=[r for r in valid if r['phase']=='quality']
    emotion_file=ROOT/'emotion-check.json'
    eiv=json.loads(emotion_file.read_text()) if emotion_file.is_file() else {}
    emotion={x['id']:x for x in eiv.get('results',[])}
    validation=json.loads((ROOT/'validation.json').read_text()) if (ROOT/'validation.json').is_file() else {}
    (ROOT/'results.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False))
    body='<nav><a href="../index.html">Study home</a><a href="../performance/index.html">GPU throughput</a><a href="../study/index.html">CFG / temperature</a><a href="https://huggingface.co/laion/Humaneness-Voice-Small">Model</a></nav>'
    body+='<p class="eyebrow">Training-free inference-time search · measured implementation</p><h1>Listen, rank, fork, continue.</h1><p>Reward-guided chunk search for Humaneness Voice Small: can we steer emotional speech while emitting irreversible audio, on one RTX 3090?</p>'
    body+='<div class="cards">'+card(str(len(valid)),'Actual output takes, including first-use checks')+card('4 / 8 / 12 / 16','Fixed parallel candidate budgets')+card('800 / 1600 ms','10 / 20 acoustic frames per search decision')+card('1 / 2','Retained prefixes; not token-level probability beams')+'</div>'
    body+='<div class="callout"><b>Systems answer: yes, within the measured envelope.</b> On one RTX 3090, warm eight-strand search measured about RTF 0.73 at 800 ms and 0.51 at 1600 ms, including ASR and quality selection. Sixteen strands measured about 1.13 at 800 ms (slower than real time), but 0.78 at 1600 ms. This is output-duration RTF, not aggregate candidate RTF or an end-to-end browser guarantee. First-use compilation can take tens of seconds.</div>'
    body+='<div class="callout warning"><b>Quality answer: a trade-off, not a universal win.</b> In the three speech-only texts × two seeds pilot, top-2/1600 ms and Best-of-8 both had zero mean measured WER. Top-2/1600 ms had a slightly higher combined selection reward but lower style CLAP. Other search variants introduced word errors, including substantial errors in a German take. Learned reward gains are not evidence of improved human naturalness.</div>'
    body+='<h2>English summary of the proposed idea</h2><p>A pretrained semantic decoder emits one conditioning vector per 80-ms acoustic frame. A local autoregressive Talker then generates the frame’s twelve acoustic tokens. Instead of finishing N independent utterances, generate N continuations for a short chunk, decode them, and score the spoken prefix and delivery. Keep either the single best prefix or the best two, clone their semantic and codec states, and generate fresh children. With a total budget of eight and width two, each retained prefix gets four children at the next step, and the best two are selected globally from the eight continuations.</p>'
    body+='<pre>Winner-of-8: shared prefix → 8 chunk continuations → score → keep 1 → fork 8\nTop-2:       shared prefix → 8 chunk continuations → score → keep 2\n             each retained prefix → 4 children → 8 total → global top 2</pre>'
    body+='<p>Width one is greedy, reward-guided chunk rollout / sequential best-of-N. Width two is a sampled, reward-guided beam-like search over audio prefixes. It is <b>not conventional token-level beam search</b> ranked by accumulated model log probability. The full prefix reward is recomputed, not summed across overlapping windows; summing would count the same words repeatedly. Future utterance-level reward is unknown, so neither mode is globally optimal.</p>'
    body+='<p><b>Architecture caveat:</b> the question describes a roughly 600M semantic backbone plus a 525M local Talker. The checkpoint actually available in this demo has approximately 715.5M total parameters and a 112.8M Talker/bridge, as documented in its model card. These timings therefore do not establish real-time performance for a different 525M-Talker model. The search mechanism applies conceptually to that architecture, but it needs a new benchmark.</p>'
    body+='<h2>What was implemented</h2><ul><li>Persistent conditional/unconditional semantic KV caches, current generation row, attention mask, finished flags and all generated acoustic frames.</li><li>Stateful incremental PCM decoding, including the codec’s per-row KV caches and offsets. Retained rows are cloned with <code>index_select</code>; duplicate children do not share mutable cache storage. The full prefix is never re-generated.</li><li>A fixed N-row batch. Width two forks N/2 children per retained prefix, then takes the global top two, not one winner from each parent.</li><li>Batched Parakeet v3 ASR with duration-derived word timestamps, and one shared VoiceCLAP audio embedding pass for style similarity, Genuineness and Burst Blend heads. Audio resampling is anti-aliased.</li><li>Fresh stochastic continuation at each step, CFG 1.5, audio temperature 1.0, top-k 50 and top-p 0.95. Reference A is held fixed. No LoRA, DPO or Luna calls in the experiments.</li></ul>'
    body+='<h2>Reward, normalization and partial WER</h2><pre>style = clip((centered_cosine + 1) / 2, 0, 1)\ngenuine = clip(genuineness / 6, 0, 1)\nblend = clip(burst_blend / 10, 0, 1)\nquality = 0.50 * style + 0.25 * genuine + 0.25 * blend\nreward = quality * max(0, 1 - prefix_WER)</pre>'
    body+='<p>Thus Genuineness plus Burst Blend jointly carry the same nominal weight as style similarity. Fixed scales keep parent/time comparisons meaningful; candidate-set min–max normalization would change the meaning of a score when one bad candidate appears or disappears. Equal nominal weights do not imply equal empirical influence: CLAP has a narrower observed range, and all three quality terms share an encoder. The bounded “inverse WER” factor is <code>1−WER</code>, not <code>1/WER</code>, which would be singular at perfect speech.</p>'
    body+='<p>The style query comes only from delivery instructions and parenthesized acting cues. Known literal transcript text and quoted material are removed; spoken content is never a fallback style query. This is style matching, <b>not a speaker-identity verification score</b>. Voice identity is conditioned by the reference, not independently checked with a speaker recognizer.</p>'
    body+='<p>At intermediate boundaries, ASR runs on the cumulative audible prefix, retaining words with end timestamps at least 120 ms before the right edge. Word Levenshtein alignment chooses the target-prefix endpoint with minimum edit count; the not-yet-spoken suffix is free, internal deletions/substitutions are not. Empty recognized speech gets a zero intelligibility gate. At EOS or the frame cap, the complete target and complete hypothesis are used. Prefix WER is a surrogate, not a valid final-utterance WER or a confidence estimate. Timestamp filtering helps but cannot guarantee a stable boundary word.</p>'
    body+='<div class="callout warning"><b>Original benchmark limitation: intentional non-speech.</b> The original measured CLAP-only implementation assigns zero reward to an intended groan, laugh or silence with empty ASR, falling back to stable row-order tie breaking. No localized burst detector was included in those measurements. A high Blend score does not prove burst presence or timing. The later optional position-aware extension below adds a narrow leading-non-speech exemption and localized matching; the old tables do not evaluate it.</div>'
    body+='<h2>Irreversible streaming versus a real beam</h2><p>Winner-of-N commits each chosen chunk immediately: discarded histories are gone forever. For top-2, only an identical acoustic-token prefix of both retained beams can be emitted. If the surviving children later share one ancestor, that shared prefix becomes streamable. Otherwise output must wait until the final winner is known. The code never plays the current leader and subsequently swaps it for another voice trajectory.</p><p>A bounded-latency variant would retain both beams for one look-ahead chunk and then commit to one ancestor, discarding incompatible histories. That is useful but changes the search into a commitment-constrained beam. It is proposed below, <b>not silently substituted for the exact common-prefix top-2 mode tested here</b>. Complete-utterance Best-of-N could likewise stream only a shared prefix; independent sampled acoustic sequences generally offer none.</p>'
    body+='<h2>One-GPU versus two-GPU performance</h2><p>One-GPU rows place every active TTS, codec, ASR and quality model on <code>cuda:0</code>, a single RTX 3090 with 24 GiB VRAM. The second card is unused for active computation. Two-GPU rows place TTS/codec on card 0 and scorers on card 1. Scoring precedes the next expansion, so a second card does not remove the sequential decision dependency. No competing GPU jobs ran during measurements; clocks were not locked.</p><p>Warm table below uses the second seed (2027) after each shape’s preceding trial. All first trials remain in the complete data, including compilation/capture costs. Each row is a measured observation, not a population average. The generation hint and hard cap were 6.6 s, quantized upward to 83 frames / 6.64 s; natural EOS was enabled and no minimum length was forced. Many outputs reached the cap, and generated trailing silence/noise remains in the RTF denominator.</p>'
    for layout,title in [('one_gpu','Single RTX 3090'),('two_gpu','Two RTX 3090s, separate scorer card')]:
        output=[]
        for n in [4,8,12,16]:
            for chunk in [10,20]:
                for width in [1,2]:
                    candidates=[r for r in measures if (r['layout'],r['n'],r['chunk_frames'],r['beam_width'],r['seed'])==(layout,n,chunk,width,2027)]
                    if not candidates:continue
                    r=candidates[0];p=r['performance']
                    output.append([str(n),str(width),str(chunk*80),f"{p['search_rtf']:.3f}",
                        f"{p['first_commit_seconds']:.3f}",f"{p['tts_codec_seconds']:.3f}",
                        f"{p['scoring_seconds']:.3f}",f"{r['peak_vram_gib'][0]:.2f}",
                        'Yes' if p['search_rtf']<1 else 'No'])
        body+=f'<h3>{title}</h3>'+table(['N','Beam width','Chunk ms','Search RTF ↓','First committed PCM, s','TTS/codec GPU s','Scoring wall s','Peak card-0 GiB','RTF &lt;1'],output)
    body+='<p><b>Search RTF = search critical-path wall seconds / final delivered raw PCM seconds.</b> It includes prompt packing/reference coding, TTS/codec, GPU transfers, cumulative-prefix ASR, timestamp processing, quality heads, CPU ranking and cache cloning. It excludes model loading, one-time style text-query embedding, Luna, MP3 encoding, optional final alignment/evaluation, HTTP and browser playback. This differs deliberately from the earlier <a href="../performance/index.html">TTS-only GPU event RTF</a>. An N-way aggregate audio throughput divided by N is not used to claim real-time playback.</p>'
    cold=sorted(measures,key=lambda r:-r['performance']['search_wall_seconds'])[:5]
    body+='<h3>First-use costs are real</h3>'+table(['Actual run','Search seconds','RTF','Graph capture s'],[[r['id'],f"{r['performance']['search_wall_seconds']:.2f}",f"{r['performance']['search_rtf']:.2f}",f"{r['performance']['graph_capture_seconds']:.2f}"] for r in cold])
    audits=[r for r in valid if r['phase']=='audit']
    if audits:
        body+='<h3>Fresh-seed speech/language stress checks</h3><p>After profiling one anger text, winner search was checked on the fear and German-affection texts with a fresh seed 12345, again on one card. These are additional systems checks, not many independent speakers.</p>'+table(['Text','N','Chunk ms','RTF','First commit s','Raw WER %'],[[r['case'],str(r['n']),str(r['chunk_frames']*80),f"{r['performance']['search_rtf']:.3f}",f"{r['performance']['first_commit_seconds']:.3f}",f"{r['final']['prefix_wer']*100:.1f}"] for r in audits])
    speech=[r for r in quality if r['case']!='burst_en']
    burst=[r for r in quality if r['case']=='burst_en']
    body+='<h2>Quality: single sample versus whole-utterance BoN versus search</h2><p>The primary comparison is three fixed texts (anger English, fear English, affection German) × two seeds × six methods = 36 selected outputs. Every method uses the same text, reference, CFG, temperature and 83-frame cap. Best-of-8 is ranked by the <b>same fixed-scale reward</b>, not the legacy UI’s candidate-min–max normalization. Equal N does not mean identical random samples or equal total compute: search evaluates many prefix sets, while BoN evaluates the finished set once. No human listening study, independent ASR or speaker-identity evaluation was performed.</p>'
    body+=quality_table(speech,emotion)
    body+='<p>The direction is mixed even under automatic evaluation: compared with Best-of-8, top-2/1600 ms lowered style CLAP (0.151 vs 0.201) and had slightly lower independently measured emotion rank percentile (0.829 vs 0.842), despite a higher combined search reward (0.574 vs 0.563). Top-2/800 ms had higher emotion rank percentile (0.882) but mean WER 14.55%. Winner-of-8/800 ms had mean WER 6.06% versus 7.73% for one sample, with an error concentrated in one take. These few observations do not establish a generally better decoder.</p>'
    body+='<h3>Paired effects versus Best-of-8</h3><p>Seeds are paired within text; bootstrap resamples the three text clusters after averaging each seed pair. With only three clusters, intervals are descriptive and very weak evidence. Negative WER deltas are better; positive quality deltas are better. This analysis is not corrected for multiple comparisons.</p>'+paired(speech)
    if burst:
        body+='<h3>Exploratory real burst / shout recipe</h3><p>After the speech-only comparison, a separate structured prompt requested a 0.3-second frustrated groan followed by angry shouted speech. No settings were re-tuned. Two seeds per method are only a diagnostic. This recipe is not comparable to the caption-only cases as an isolated causal emotion effect.</p>'+quality_table(burst,emotion)
    body+='<h3>Independent emotion-model check</h3><p>The post-search check uses the Empathic-Insight-Voice-Small heads with the documented <code>mkrausio/EmoWhisper-AnS-Small-v0.1</code> encoder and ReLU activation, on raw output. This encoder/head set was <b>not</b> used for selection. Actual loaded head count: '+esc(eiv.get('head_count','pending'))+'. Rank percentile is normalized by this actual count, not interpreted as a probability or an intensity guarantee. It provides a differently modeled diagnostic, still not a human rating. ASR, Genuineness, Blend and CLAP endpoint scores reuse the ranking models and are vulnerable to selection/reward hacking.</p>'
    body+='<h2>Correctness and practical UI behavior</h2><pre>'+esc(json.dumps(validation,indent=2))+'</pre><p>The validation checks one four-row / twenty-frame trajectory. With a constant selector, chunk-search continuation produced exactly the same acoustic tokens and PCM as the optimized normal stream’s first row. Concatenated emitted chunks exactly equaled the final raw PCM. Independently loaded packaged head towers matched the shared VoiceCLAP embedding numerically. These checks do not prove all future cache revisions or human perceptual quality; unknown codec state shapes fail closed.</p>'
    body+='<h3 id="adaptive-reward">Optional adaptive reward extension</h3><p>The live UI now offers the original VoiceCLAP style reward, Luna-selected dimensions, or manual dimension targets/weights. The pinned catalog includes 57 VoiceNet dimensions and 55 documented Empathic Insight Plus experts (40 emotions, 11 attributes, four pooled quality heads). Select 1–4 distinct terms across either family. Four EIV+ heads with unverified native ranges are not offered. Luna sees the audible acting direction rather than using the literal transcript as a style target; its proposal is validated and can be previewed/edited.</p><p>Each scalar is clipped after fixed native-scale normalization to 0–1. Maximize uses x, minimize uses 1−x, and target utility uses 1−|x−target_normalized|. Positive term weights are normalized to sum 1. The default quality mix remains 50% selected style, 25% Genuineness and 25% Burst Blend, multiplied by max(0,1−WER). The style fraction is editable. These are proxy utilities, not probabilities, calibrated human MOS or guaranteed quality improvements. Expected empirical EIV+ quality ranges are not hard physical bounds.</p><p>VoiceNet uses the official GELU heads with a byte-validated shared VoiceCLAP tower. EIV+ uses the documented pinned BUD-E-Whisper encoder, ReLU experts, full flattened features for emotions and mean/min/max/std pooled features for quality. Only selected EIV+ heads are resident; candidates are processed in groups of four, and clips longer than 30 seconds use the latest 30-second EIV+ window. Planner/model-loading time is separately shown and excluded from search RTF; active dimension inference is included. <b>The preceding CLAP-only throughput/quality tables do not benchmark this extension.</b> Sources: <a href="https://huggingface.co/laion/voicenet-dimension-predictors-commercial">VoiceNet model card and taxonomy</a>, <a href="https://huggingface.co/laion/Empathic-Insight-Voice-Plus">EIV+ native ranges and inference</a>.</p>'
    adaptive_validation=settings.HERE/'test-results/adaptive-validation.json'
    if adaptive_validation.is_file():
        check=json.loads(adaptive_validation.read_text())
        body+='<p>A real two-row GPU numerical check compared Arousal/Ranting with upstream GELU inference, and Anger/Speech Quality with an independent serialized-weight ReLU/pooling computation. Maximum absolute score difference: '+f"{max(check['independent_native_score_abs_differences'].values()):.8f}"+'. This is an implementation smoke test, not perceptual validation or an isolated complete-search speed benchmark.</p>'
    adaptive_browser=settings.HERE/'test-results/adaptive-browser.json'
    if adaptive_browser.is_file():
        smoke=json.loads(adaptive_browser.read_text())
        body+='<p>Additional real HTTPS developer smoke checks passed for manual native-scale editing, Luna preview and automatic selection, mixed heads, BS 4/16 search, Best-of-4, legacy scoring and mobile layout. The following latest live <b>two-card</b> smoke observations are not an isolated benchmark, repeated quality study or end-to-end/network RTF. The BS-16 mixed case is slightly slower than real time here.</p>'+table(
            ['Developer case','Selected terms','Search + scoring RTF','Planner s','Head/model setup s'],
            [[r['case'],str(len((r['plan'] or {}).get('terms',[]))),
              f"{r['search_rtf']:.3f}" if r['search_rtf'] is not None else 'Not a search run',
              f"{r['reward_planning_ms']/1000:.3f}",f"{r['reward_loading_ms']/1000:.3f}"] for r in smoke])
    body+='<h3 id="burst-reward">Optional position-aware vocal-burst extension</h3><p>A separate UI selector, <b>off by default</b>, adds locator-only position/duration checking or locator + commercial type checking to either the CLAP reward or the adaptive dimension reward. Targets come from explicit burst tags in the actual GENERAL/SCRIPT conditioning or 1–8 manual label/start/duration requests. Manual targets do not insert sounds into the generation prompt; the acting direction must request them too. No explicit targets means no burst addition and no change to previous ranking.</p>'
    body+='<p>For scripts, the default timing is the gap between exact-matched Parakeet word timestamps. It tolerates variable speaking tempo, with duration-aware penalties and reduced credit for events extending into neighboring speech. Missing word anchors are reported, not guessed. Fixed script-clock times are an alternative; duration tags determine these times, while untimed speech uses an explicit 0.36-second-per-word heuristic (at least 0.4 seconds per segment). Manual requests use absolute time. A global one-to-one assignment prevents one detected event satisfying multiple requests. Default burst share is 25%, onset/slot tolerance 0.3 seconds, and type matching uses class families.</p>'
    body+='<pre>event_match = timing * slot_overlap * sqrt(min(actual_duration, requested_duration)\n                                        / max(actual_duration, requested_duration))\n              * locator_confidence * class_or_family_probability\nburst_score = max(0, mean(one-to-one target matches, missing=0) - extra_penalty)\nquality = (1 - burst_share) * base_quality + burst_share * burst_score\nreward = quality * max(0, 1 - WER)</pre>'
    body+='<p>Clock timing decreases linearly with onset error to zero at the tolerance limit. Word-gap timing decreases outside the slot; overlap is the fraction of an event inside the tolerance-expanded slot. Unsupported types receive explicit <b>location-only</b> checking rather than a fabricated class score. Future requests remain pending and are excluded from the mean during prefix search; all requests are scored at completion. Only intentional leading non-speech before speech is due may bypass an empty-prefix ASR gate; final full-transcript WER is never bypassed. Optional extra-event penalties are applied only at completion and capped at 0.15. Enabled CLAP+burst Best-of-N uses fixed search-style 50/25/25 base quality instead of the legacy within-set normalization. Adaptive base quality otherwise remains unchanged.</p>'
    body+='<p>The separately trained Whisper <a href="https://huggingface.co/laion/vocalburst-locator">locator</a> is pinned to revision 3e4a8392 and explicitly uses <b>model_v2.pt</b>, threshold 0.5, merge gap 0.1 seconds and minimum duration 0.1 seconds. The published helper defaults to v1 settings; those are not used. Output is cropped to physical PCM duration, with overlapping 30-second windows covering longer prefixes. Only localized event crops enter the <a href="https://huggingface.co/laion/vocal-burst-detector-commercial">commercial classifier</a> (revision 67bbf412), using the shared byte-validated VoiceCLAP tower, all five BatchNorm/GELU heads, averaged logits and then softmax. It supports 16 burst types plus no_burst; several types are unreliable in the upstream held-out evaluation. Family probabilities and locator confidence are noisy model proxies, not independent human verification or proof of improved naturalness.</p>'
    body+='<p>The locator adds another encoder; initial download/loading is separately displayed, while active localization, class inference and CPU matching are included in search/scoring RTF. <b>Previous one-card CLAP-only speed and quality tables do not apply to this option.</b> No real-time or quality-improvement guarantee is made. The current live demo normally puts TTS on one card and scoring on a second card.</p>'
    burst_validation=settings.HERE/'test-results/burst-validation.json'
    if burst_validation.is_file():
        check=json.loads(burst_validation.read_text())
        body+='<p>Real GPU implementation checks matched pinned official locator logits and an independent functional five-head classifier: maximum absolute differences '+f"{check['locator_logit_max_abs_difference']:.8f}"+' and '+f"{check['classifier_probability_max_abs_difference']:.8f}"+'. Six existing synthetic burst-recipe samples produced localized events; a self-derived timing control scored '+f"{check['position_control']['aligned']:.3f}"+' when aligned and '+f"{check['position_control']['shifted_one_second']:.3f}"+' after shifting its event one second. A real '+f"{check['long_prefix_seconds']:.1f}"+'-second input checked overlapping-window coverage and physical extent. <b>These are implementation/position controls, not independent detector accuracy or perceptual quality evidence.</b></p>'
    burst_browser=settings.HERE/'test-results/burst-browser.json'
    if burst_browser.is_file():
        smoke=json.loads(burst_browser.read_text())
        body+='<p>Real HTTPS Chromium checks covered manual targets, script word slots, family classification, combination with adaptive VoiceNet, Best-of-4, winner/Top-2 searches at 800/1600 ms, off/no-target regressions, the eight-target limit and mobile layout. Latest live two-card smoke observations below include scoring but exclude network and model preparation. These few examples are <b>not a repeated throughput or quality study</b>; a missed burst correctly receives zero.</p>'+table(
            ['Developer case','Search RTF','Active burst scoring s','Winner WER','Final burst score'],
            [[r['case'],f"{r['search_rtf']:.3f}" if r['search_rtf'] is not None else 'Not a search run',
              f"{r['burst_scoring_seconds']:.3f}" if r['burst_scoring_seconds'] is not None else 'Final scoring only',
              f"{min(r['scores'],key=lambda c:c['rank'])['wer']:.3f}",
              f"{min(r['scores'],key=lambda c:c['rank'])['burst_alignment']['score']:.3f}" if (r['burst_request'] or {}).get('active') else 'Disabled/inactive'] for r in smoke])
    browser_check=settings.HERE/'test-results/search-browser.json'
    if browser_check.is_file():
        checked=json.loads(browser_check.read_text())
        if len(checked)==5 and {r['n'] for r in checked}=={1,3,4,8,16}:
            body+='<p>Actual HTTPS Chromium integration checks passed at BS 1, 3, 4, 8 and 16 across both chunk sizes. The checks verified all 1–16 UI options, effective single-path behavior at BS 1, audio arriving before the completed result, decoded MP3 segment durations matching raw PCM duration without encoder-padding gaps, mono 96-kbps encoding, session-private audio access and mobile layout. These developer smoke tests used the live two-card deployment and are separate from the isolated one-card throughput/quality measurements; they do not establish performance for every intermediate BS.</p>'
    body+='<p>The live demo adds two generation modes, every batch size from 1 through 16, 800/1600-ms search chunks and a configurable duration cap. Top-2 divides N children between the retained prefixes; for odd N the higher-ranked prefix receives the extra child (e.g. 4+3 for BS 7). BS 1 uses one path in either mode. The isolated throughput measurements above cover N=4/8/12/16, not every intermediate size; a newly used shape may require first-use compilation. The demo sends mono 96-kbps MP3 segments as soon as PCM is committed, schedules decoded segments using Web Audio, and keeps the final complete take downloadable. Live audio is raw; forced-alignment fades apply only to the finished take and cannot retroactively alter audio already heard. Private reference uploads and generated chunks keep the existing session isolation and one-hour cleanup. The browser stream may underrun despite model RTF &lt;1 if compilation, HTTP/MP3 decoding or a delayed beam commitment exhausts its buffer.</p>'
    body+='<h2>Assessment and improvements worth pursuing</h2><ol><li><b>Use winner-of-8 at 800 ms for a low-delay starting point; use 1600 ms for more throughput headroom.</b> Sixteen strands need 1600 ms in these measurements. Keep search optional: it is not proven to beat BoN for overall voice quality.</li><li><b>Protect semantic progress.</b> Prefix-WER can prefer slowing down or an easy partial phrase. Add monotonic alignment/progress constraints, expected speech/non-speech masks and calibrated uncertainty for short ASR spans; use complete-target WER at completion.</li><li><b>Control burst timing and identity separately.</b> Add a localized burst-presence term or hard eligibility check for actual requested events, and a consented reference-speaker embedding constraint. Blend and style CLAP alone cannot verify either.</li><li><b>Bound beam latency explicitly.</b> Offer a one-chunk look-ahead commitment-constrained beam as a distinct mode, or keep an exact top-2 mode and show when output must wait. Do not splice unrelated beam PCM or crossfade to hide incompatible histories.</li><li><b>Preserve diversity.</b> Two near-identical children of one parent can eliminate the other promising beam immediately. Consider per-parent diversity quotas, distinct acoustic-prefix deduplication or soft/particle resampling, with a clearly changed selection rule.</li><li><b>Calibrate and audit the reward.</b> Learn fixed percentile scales on an external calibration set, validate held-out emotions/texts/voices and use blind human pairwise listening. More search can exploit a proxy rather than improve speech; a CLAP/Genuine/Blend shared backbone is not three independent judges.</li><li><b>Reduce repeated scoring work.</b> The biggest implemented saving is one batch embedding instead of three encodes per candidate. Prefix rescoring still re-encodes cumulative audio; a truly cached streaming ASR/quality encoder, bounded rolling windows plus transcript progress, and shortlist-first scoring could help. They require new accuracy/cost checks, not merely smaller windows.</li><li><b>Keep model likelihood as a safety signal.</b> Track per-frame probability/entropy and apply a calibrated plausibility constraint or KL-style regularizer, rather than selecting arbitrarily off-model prefixes solely by a noisy short-window proxy. This is a future extension, not a measured result here.</li></ol>'
    body+='<h2>All measured output takes</h2><p>Each row is a selected final output, not every discarded branch. Complete per-chunk candidate scores and retained row indices are in the JSON; discarded branch audio was not archived. Filter by phase, method, case, N, beam or chunk. Playback files are raw generated mono MP3s, not source references.</p><input id="filter" placeholder="quality affection_de b2 c20" style="width:100%;padding:10px;background:var(--panel);color:var(--fg);border:1px solid var(--line)"><p id="count"></p><div id="takes"></div>'
    compact=[{'id':r['id'],'audio':r['audio'],'wer':r['final']['prefix_wer'],'reward':r['final']['reward'],
        'hyp':r['final']['hyp'],'rtf':r['performance']['search_rtf'],'first':r['performance']['first_commit_seconds']} for r in valid]
    body+='<script>const samples='+json.dumps(compact,ensure_ascii=False).replace('<','\\u003c')+';'+r'''
const takes=document.getElementById('takes'),filter=document.getElementById('filter');
function render(){const terms=filter.value.toLowerCase().split(/\s+/).filter(Boolean);const rows=samples.filter(r=>terms.every(t=>r.id.toLowerCase().includes(t)));takes.replaceChildren();document.getElementById('count').textContent=rows.length+' matches; showing first 60.';for(const r of rows.slice(0,60)){const d=document.createElement('details'),s=document.createElement('summary');s.textContent=r.id+' · WER '+(r.wer*100).toFixed(1)+'% · RTF '+r.rtf.toFixed(3);d.append(s);const a=document.createElement('audio');a.controls=true;a.preload='none';a.src=r.audio;d.append(a);const pre=document.createElement('pre');pre.textContent='ASR: '+r.hyp+'\nReward: '+r.reward.toFixed(3)+'\nFirst committed PCM: '+r.first.toFixed(3)+' s';d.append(pre);takes.append(d);}}filter.addEventListener('input',render);render();
</script>'''
    body+='<h2>Reproducibility and sources</h2><p><a href="design.json">Design/environment</a> · <a href="results.json">All measured results and chunk traces</a> · <a href="validation.json">Cache/embedding validation</a> · <a href="emotion-check.json">Unselected emotion-model evaluation</a> · <a href="../code/README.md">Implementation and reproduction notes</a></p><p><a href="https://huggingface.co/nvidia/parakeet-tdt-0.6b-v3">NVIDIA Parakeet v3 model card</a> documents multilingual support and timestamp capabilities. <a href="https://github.com/huggingface/transformers/blob/main/docs/source/en/model_doc/parakeet.md">Official Transformers Parakeet implementation/docs</a> describe duration/timestamp handling. <a href="https://arxiv.org/abs/2506.19248">Inference-Time Reward Hacking in Large Language Models</a> motivates a proxy-hacking caution by analogy, not direct evidence for this TTS model.</p>'
    body+='<footer>30 September 2026 · LAION / Humaneness Voice Small S3 revision '+esc(settings.REVISION)+' · All audio is synthetic. One non-neutral positive-valence-labelled speech reference, two seeds in the quality pilot, no human MOS. Reference recordings and user uploads are not published.</footer>'
    html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Humaneness Voice Small — reward-guided chunk search</title><style>'+CSS+'</style></head><body><main>'+body+'</main></body></html>'
    (ROOT/'index.html').write_text(html)
    print(json.dumps({'takes':len(valid),'measure':len(measures),'quality':len(quality),'audit':len(audits),
                      'emotion_checks':len(emotion),'errors':len(rows)-len(valid)}),flush=True)


